# Generated by build.py from recipe.yml for recipe https-log-in-with-tls-srp. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'tpasswd'), "device:not-a-verifier:not-a-salt:1`n")
[IO.File]::WriteAllText((Join-Path $PWD 'tpasswd.conf'), "1:zz:2`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--log-file', 'srp.log', '--tlsuser', 'device', '--tlspassword', 's3cret', 'https://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -k --tlsauthtype SRP --tlsuser device --tlspassword s3cret https://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
